WITH scored AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, PERCENT_RANK() OVER (ORDER BY discount) AS discount_percent_rank, ROW_NUMBER() OVER (PARTITION BY status ORDER BY discount, id) AS event_seq, LAG(discount, 1) OVER (ORDER BY shipping_fee, id) AS prev_discount FROM orders) SELECT id, status, channel, amount, shipping_fee, event_seq, prev_discount, CASE WHEN status RLIKE '^(PENDING|RETURNED)$' THEN 'EXTENDED' WHEN status RLIKE '^(COMPLETED|CANCELLED)$' THEN 'GROUP_B' ELSE 'GROUP_A' END AS status_zone FROM scored ORDER BY amount DESC NULLS LAST;
